import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';

test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns single overdue invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-10',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[0].dueDate, '2026-10-10');
  assert.equal(result[0].daysOverdue, 10);
  assert.equal(result[0].due, 102850);
});

